using System.Security.Cryptography;using System.Text;using System.Text.Json;using Microsoft.Extensions.Logging;using WAID.Application.Abstractions;using WAID.Infrastructure.PowerShell;namespace WAID.Infrastructure.Diagnostics;
public sealed class WindowsStorageEvidenceProvider(IPowerShellRunner ps):IStorageEvidenceProvider{private const string Script="""$disks=@(Get-PhysicalDisk -ErrorAction SilentlyContinue|ForEach-Object{$r=$_|Get-StorageReliabilityCounter -ErrorAction SilentlyContinue;[pscustomobject]@{id="$($_.UniqueId)";name=$_.FriendlyName;media="$($_.MediaType)";bus="$($_.BusType)";size=[long]$_.Size;health="$($_.HealthStatus)";operation=(@($_.OperationalStatus)-join',');temp=$r.Temperature;wear=$r.Wear;read=$r.ReadLatencyMax;write=$r.WriteLatencyMax;reference="StorageManagement:PhysicalDisk:$($_.DeviceId)"}});$volumes=@(Get-Volume -ErrorAction SilentlyContinue|Where-Object{$_.Size-gt0}|ForEach-Object{[pscustomobject]@{id="$($_.UniqueId)";label=$_.FileSystemLabel;fs=$_.FileSystem;size=[long]$_.Size;free=[long]$_.SizeRemaining;health="$($_.HealthStatus)";reference="StorageManagement:Volume:$($_.DriveLetter)"}});$events=@(Get-WinEvent -FilterHashtable @{LogName='System';StartTime=(Get-Date).AddDays(-30);Id=7,11,51,55,98,129,153} -ErrorAction SilentlyContinue|Select-Object -First 200|ForEach-Object{[pscustomobject]@{time=$_.TimeCreated.ToUniversalTime().ToString('O');volume='unknown';id=$_.Id;summary=$_.Message;reference="EventLog:System:$($_.RecordId)"}});[pscustomobject]@{disks=$disks;volumes=$volumes;events=$events}|ConvertTo-Json -Depth 6 -Compress""";public async Task<StorageSnapshot> CollectAsync(CancellationToken t){var r=await ps.RunAsync(Script,new Dictionary<string,object?>(),t).ConfigureAwait(false);if(!r.Succeeded)throw new StorageHealthException("WAID-STORAGE-COLLECT","Storage evidence could not be collected.",string.Join("; ",r.Errors));var p=JsonSerializer.Deserialize<Payload>(string.Join(Environment.NewLine,r.Output),Options)??throw new StorageHealthException("WAID-STORAGE-DATA","Windows returned empty storage evidence.","No payload.");var now=DateTimeOffset.UtcNow;var disks=(p.Disks??[]).Where(x=>x.Size>0).Select(x=>new PhysicalDiskHealth(Hash(x.Id),Clean(x.Name),Clean(x.Media),Clean(x.Bus),x.Size,Clean(x.Health),Clean(x.Operation),Metric(x.Temp,0,150),Metric(x.Wear,0,100),Metric(x.Read,0,60000),Metric(x.Write,0,60000),Clean(x.Reference))).ToArray();var volumes=(p.Volumes??[]).Where(x=>x.Size>0).Select(x=>new VolumeHealth(Hash(x.Id),Clean(x.Label),Clean(x.Fs),x.Size,Math.Clamp(x.Free,0,x.Size),Clean(x.Health),Clean(x.Reference))).ToArray();var events=(p.Events??[]).Where(x=>DateTimeOffset.TryParse(x.Time,out _)).Select(x=>new FileSystemEvent(DateTimeOffset.Parse(x.Time!).ToUniversalTime(),Hash(x.Volume),x.Id,Clean(x.Summary,500),Clean(x.Reference))).ToArray();var limits=new List<string>();if(disks.Any(x=>x.TemperatureCelsius is null||x.WearPercent is null))limits.Add("Temperature or wear is unavailable for one or more devices; vendor support varies and no healthy state is inferred.");return new(now,disks,volumes,events,limits);}private static double? Metric(double? x,double min,double max)=>x>=min&&x<=max?x:null;private static string Hash(string? x)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(x??"unknown")))[..20];private static string Clean(string? x,int max=200){var s=(x??"").Replace(Environment.UserName,"[user]",StringComparison.OrdinalIgnoreCase).Trim();return s.Length<=max?s:s[..max];}private static readonly JsonSerializerOptions Options=new(){PropertyNameCaseInsensitive=true};private sealed record Payload(DiskDto[]? Disks,VolumeDto[]? Volumes,EventDto[]? Events);private sealed record DiskDto(string? Id,string? Name,string? Media,string? Bus,long Size,string? Health,string? Operation,double? Temp,double? Wear,double? Read,double? Write,string? Reference);private sealed record VolumeDto(string? Id,string? Label,string? Fs,long Size,long Free,string? Health,string? Reference);private sealed record EventDto(string? Time,string? Volume,int Id,string? Summary,string? Reference);}
public sealed class StorageHealthCenter(IStorageEvidenceProvider provider,IStorageHealthRepository repo,ICleanupEstimator cleanup,ILogger<StorageHealthCenter> log):IStorageHealthCenter{public async Task<StorageHealthReport> AnalyzeAsync(CancellationToken t){var s=await provider.CollectAsync(t).ConfigureAwait(false);var previous=await repo.GetLatestAsync(t).ConfigureAwait(false);var report=new StorageHealthReport(Guid.NewGuid(),s.CollectedAtUtc,s.Disks,s.Volumes,Evaluate(s),Trends(previous,s),await cleanup.EstimateAsync(t).ConfigureAwait(false),s.Limitations);await repo.SaveAsync(s,report,t).ConfigureAwait(false);log.LogInformation("Storage analysis {ReportId} stored {DiskCount} disks and {WarningCount} warnings",report.Id,report.Disks.Count,report.Warnings.Count);return report;}public static IReadOnlyList<StorageWarning> Evaluate(StorageSnapshot s){var a=new List<StorageWarning>();void Add(StorageConcern c,string id,string title,string explanation,string severity,double confidence,StorageEvidence[] ev)=>a.Add(new(c,id,title,explanation,severity,confidence,ev));foreach(var v in s.Volumes){var pct=v.SizeBytes==0?0:(double)v.FreeBytes/v.SizeBytes*100;if(pct<10)Add(StorageConcern.Capacity,v.Id,"Volume space is low",$"{pct:F1}% free remains.",pct<5?"Critical":"Warning",.99,[new("freePercent",pct.ToString("F1"),v.SourceReference,s.CollectedAtUtc)]);}foreach(var d in s.Disks){if(!d.HealthStatus.Equals("Healthy",StringComparison.OrdinalIgnoreCase))Add(StorageConcern.Smart,d.Id,"Device health requires attention","Windows Storage Management reports a non-healthy state. Vendor SMART semantics vary.","Critical",.9,[new("health",d.HealthStatus,d.SourceReference,s.CollectedAtUtc)]);if(d.TemperatureCelsius>=60)Add(StorageConcern.Temperature,d.Id,"Storage temperature is high",$"Reported temperature is {d.TemperatureCelsius:F0}°C.",d.TemperatureCelsius>=70?"Critical":"Warning",.82,[new("temperatureC",d.TemperatureCelsius.Value.ToString("F0"),d.SourceReference,s.CollectedAtUtc)]);if(d.WearPercent>=80)Add(StorageConcern.Wear,d.Id,"Reported device wear is high",$"The provider reports {d.WearPercent:F0}% wear. Confirm with the manufacturer tool.","Warning",.75,[new("wearPercent",d.WearPercent.Value.ToString("F0"),d.SourceReference,s.CollectedAtUtc)]);if(d.ReadLatencyMilliseconds>=100||d.WriteLatencyMilliseconds>=100)Add(StorageConcern.Performance,d.Id,"Storage latency is elevated","A provider-reported maximum latency exceeded 100 ms; short spikes do not prove failure.","Warning",.7,[new("readLatencyMs",d.ReadLatencyMilliseconds?.ToString("F1")??"unknown",d.SourceReference,s.CollectedAtUtc),new("writeLatencyMs",d.WriteLatencyMilliseconds?.ToString("F1")??"unknown",d.SourceReference,s.CollectedAtUtc)]);}foreach(var e in s.FileSystemEvents)Add(StorageConcern.FileSystem,e.VolumeId,"Recent filesystem or storage event",e.Summary,"Warning",.85,[new("eventId",e.EventId.ToString(),e.SourceReference,e.OccurredAtUtc)]);return a;}private static IReadOnlyList<StorageTrend> Trends(StorageHealthReport? p,StorageSnapshot s){if(p is null)return[];var old=p.Volumes.ToDictionary(x=>x.Id);return s.Volumes.Where(x=>old.ContainsKey(x.Id)).Select(x=>new StorageTrend(x.Id,"FreeBytes",old[x.Id].FreeBytes,x.FreeBytes,x.FreeBytes-old[x.Id].FreeBytes,s.CollectedAtUtc)).ToArray();}}
public sealed class SafeCleanupEstimator:ICleanupEstimator{public Task<IReadOnlyList<CleanupEstimate>> EstimateAsync(CancellationToken t){t.ThrowIfCancellationRequested();var candidates=new[]{("Temporary files",Path.GetTempPath()),("Windows error reports",Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.CommonApplicationData),"Microsoft","Windows","WER","ReportArchive"))};IReadOnlyList<CleanupEstimate> r=candidates.Select(x=>Estimate(x.Item1,x.Item2,t)).ToArray();return Task.FromResult(r);}private static CleanupEstimate Estimate(string category,string path,CancellationToken t){long bytes=0;try{foreach(var f in Directory.EnumerateFiles(path,"*",SearchOption.AllDirectories).Take(100000)){t.ThrowIfCancellationRequested();try{bytes+=new FileInfo(f).Length;}catch(IOException){}catch(UnauthorizedAccessException){}}}catch(DirectoryNotFoundException){}catch(UnauthorizedAccessException){}return new(category,Redact(path),bytes,true,false,string.Empty);}private static string Redact(string p)=>p.Replace(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"%USERPROFILE%",StringComparison.OrdinalIgnoreCase);}
public sealed class LargeFolderAnalyzer:ILargeFolderAnalyzer{public Task<FolderSizeResult> AnalyzeAsync(string path,CancellationToken t)=>Task.Run(()=>Analyze(path,t),CancellationToken.None);private static FolderSizeResult Analyze(string path,CancellationToken t){if(string.IsNullOrWhiteSpace(path)||!Path.IsPathFullyQualified(path))throw new ArgumentException("An absolute folder path is required.",nameof(path));long bytes=0,files=0,dirs=0;var denied=new List<string>();var q=new Queue<string>();q.Enqueue(path);try{while(q.Count>0){t.ThrowIfCancellationRequested();var d=q.Dequeue();dirs++;try{foreach(var f in Directory.EnumerateFiles(d)){t.ThrowIfCancellationRequested();try{bytes+=new FileInfo(f).Length;files++;}catch(IOException){}}foreach(var child in Directory.EnumerateDirectories(d))q.Enqueue(child);}catch(UnauthorizedAccessException){denied.Add(Redact(d));}catch(IOException){denied.Add(Redact(d));}}return new(Redact(path),bytes,files,dirs,denied,false);}catch(OperationCanceledException){return new(Redact(path),bytes,files,dirs,denied,true);}}private static string Redact(string p)=>p.Replace(Environment.GetFolderPath(Environment.SpecialFolder.UserProfile),"%USERPROFILE%",StringComparison.OrdinalIgnoreCase);}
public sealed class StorageHealthException(string code,string message,string detail):InvalidOperationException(message){public string Code{get;}=code;public string Detail{get;}=detail;}
